/* Original formative questions. Each criterion is worth one mark. */
const practiceSets = [
  {id:'year11-pilot',revision:1,year:11,title:'Year 11 · Foundations in context',minutes:45,
    description:'Python, data, databases and security. Eight short answers and two extended responses; 30 marks.',
    questions:[
      {id:'y11-1',type:'Short answer',title:'Trace a selection',topic:'Programming',chapter:'selection',
        prompt:'Write the exact output, in order, for this Python program.',
        code:'score = 7\nif score >= 5:\n    score = score + 2\nelse:\n    score = score - 1\nprint(score)\nprint(score > 10)',
        criteria:['First output is 9.','Second output is False (Python Boolean spelling).'],
        model:'9\nFalse\nThe condition is true, so 2 is added to 7. Nine is not greater than ten.',
        mistake:'Do not execute both branches or print the condition instead of the final comparison.'},
      {id:'y11-2',type:'Short answer',title:'Represent a value',topic:'Data representation',chapter:'representation',
        prompt:'Convert decimal 45 to an eight-bit binary value. Show a place-value calculation to support your answer.',
        criteria:['Binary result is 00101101.','Working correctly combines place values 32 + 8 + 4 + 1 = 45.'],
        model:'00101101\n32 + 8 + 4 + 1 = 45. The 128, 64, 16 and 2 positions are zero.',
        mistake:'Write all eight bits. Correct equivalent place-value working is acceptable.'},
      {id:'y11-3',type:'Short answer',title:'Validation and verification',topic:'Data quality',chapter:'database-foundations',
        prompt:'A club enters member ages from paper forms. Explain the difference between validating an age and verifying the entered age.',
        criteria:['Validation checks whether an age meets stated rules, such as an integer within an allowed range.','Verification checks that the entered age matches the source form; it does not establish that the original age is true.'],
        model:'Validation checks an age against rules, such as a permitted numeric range. Verification compares the entered age with the paper form to check it was copied accurately. An incorrect age on the form can still be copied correctly.',
        mistake:'A valid value is not necessarily the true age. Award equivalent explanations without requiring the model wording.'},
      {id:'y11-4',type:'Short answer',title:'Choose a primary key',topic:'Databases',chapter:'entities-relationships',
        prompt:'A Member table has MemberID, GivenName and FamilyName. MemberID is unique and never empty. Explain why MemberID is a better primary key than FamilyName.',
        criteria:['MemberID uniquely identifies each member record.','Family names may repeat, so FamilyName cannot reliably identify one record.'],
        model:'Each MemberID identifies exactly one member. Two members can share a family name, making FamilyName unsuitable as a unique identifier.',
        mistake:'Do not assume names are unique. A primary key also cannot be null.'},
      {id:'y11-5',type:'Short answer',title:'Filter a table',topic:'SQL',chapter:'sql-basics',
        prompt:'Loan(LoanID, MemberID, Returned) stores Returned as 0 for an active loan and 1 for a returned loan. Write SQL to display only LoanID for active loans.',
        criteria:['SELECT LoanID FROM Loan identifies the required field and table.','WHERE Returned = 0 correctly filters active loans.'],
        model:'SELECT LoanID\nFROM Loan\nWHERE Returned = 0;\nSQL keyword case and a missing final semicolon do not affect these marks. Equivalent SQL that returns the requested result is acceptable.',
        mistake:'Returned = 1 selects completed loans. Selecting every field does not meet the requested output.'},
      {id:'y11-6',type:'Short answer',title:'Respond to phishing',topic:'Security',chapter:'security-threats',
        prompt:'An unexpected email demands your school password through an unfamiliar link. Identify one warning sign from the scenario and one suitable response.',
        criteria:['Identifies the unexpected password request, unfamiliar link or pressure to act as a warning sign.','Does not use the link or disclose the password; reports it through the school process or verifies through a known independent channel.'],
        model:'The unfamiliar link requesting a password is suspicious. Do not follow it or send credentials; report the message using the school process. Independently contact support through a known address if needed.',
        mistake:'Replying to the suspicious sender is not independent verification. A warning sign is evidence for caution, not proof on its own.'},
      {id:'y11-7',type:'Short answer',title:'Trace a list',topic:'Programming',chapter:'arrays',
        prompt:'Write the final values of total and len(values) after this code runs.',
        code:'values = [4, 1, 3]\ntotal = 0\nfor value in values:\n    total = total + value',
        criteria:['Final total is 8.','len(values) is 3.'],
        model:'total = 8\nlen(values) = 3\nThe loop visits three items and adds each value once.',
        mistake:'The length counts items, not their sum. The loop does not alter the list.'},
      {id:'y11-8',type:'Short answer',title:'Test a boundary',topic:'Testing',chapter:'selection',
        prompt:'A program accepts an integer only when 1 <= quantity <= 5. Give one valid boundary input and one invalid input immediately outside a boundary, with the expected acceptance result for each.',
        criteria:['Gives 1 or 5 and correctly expects acceptance.','Gives 0 or 6 and correctly expects rejection.'],
        model:'1 → accepted.\n0 → rejected.\nAlternatively, 5 → accepted and 6 → rejected. Either appropriate boundary can be used for each part.',
        mistake:'A typical valid value such as 3 does not test a boundary. Include the expected result.'},
      {id:'y11-9',type:'Extended response',title:'Design a score summary',topic:'Programming and testing',chapter:'arrays',
        prompt:'A Pygame game stores each round score in a one-dimensional list. Scores are whole numbers from 0 to 50. Design an algorithm, using pseudocode or Python, to display the number of rounds, total score and highest score. Handle an empty list explicitly. Explain two useful tests, including inputs and expected results. You do not need to write Pygame drawing code.',
        criteria:['Checks for an empty list before trying to read its first item.','For an empty list, reports zero rounds/total and no highest score (or a clear no-rounds message).','For a non-empty list, correctly obtains the number of rounds.','Correctly accumulates the total across all items.','Correctly finds the maximum, with valid initialisation (for example, the first item).','Gives a non-empty test with correct expected count, total and maximum.','Gives an empty-list test with the expected no-rounds behaviour.'],
        model:'IF length(scores) = 0 THEN\n    DISPLAY "No rounds", 0, 0, "No highest score"\nELSE\n    total ← 0\n    highest ← scores[0]\n    FOR EACH score IN scores\n        total ← total + score\n        IF score > highest THEN\n            highest ← score\n        ENDIF\n    NEXT score\n    DISPLAY length(scores), total, highest\nENDIF\n\nTest [10, 0, 30]: 3 rounds, total 40, highest 30. Test []: zero rounds and total, no highest score. Correct equivalent algorithms are acceptable, including suitable built-ins because this question does not prohibit them.',
        mistake:'Do not index scores[0] before checking for an empty list. A test needs expected results, not just an input.'},
      {id:'y11-10',type:'Extended response',title:'Protect a club loan register',topic:'Databases and security',chapter:'entities-relationships',
        prompt:'A school club records members and equipment loans. Each member may have many loans; each loan belongs to one member. Design two related tables, identifying a primary key for each and the foreign key. Explain how the design avoids repeating member details in every loan. Then propose a staff access control and a recovery measure, explaining how each helps.',
        criteria:['Defines a Member table with MemberID as its primary key and suitable member fields.','Defines a Loan table with LoanID as its primary key and suitable loan fields.','Places MemberID as a foreign key in Loan referencing Member.MemberID.','Correctly describes the one-member-to-many-loans relationship.','Explains that storing member details once reduces duplication or inconsistent updates.','Proposes restricted staff accounts/permissions and explains limiting unauthorised access or changes.','Proposes regular backups with restore testing and explains recovery after loss/corruption.'],
        model:'Member(MemberID PK, GivenName, FamilyName)\nLoan(LoanID PK, MemberID FK, ItemDescription, DueDate, Returned)\nLoan.MemberID references Member.MemberID. One member can have many loans, while each loan references one member. Names are stored once in Member, so updating a name does not require editing every loan. Limit editing to authorised club staff using individual accounts and suitable permissions. Make regular separate backups and test restoration so records can be recovered after loss or corruption. Equivalent field choices and suitable explained controls are acceptable.',
        mistake:'Do not place a single LoanID in Member to represent all loans. Backups support recovery; they do not prevent unauthorised access.'}
    ]},
  {id:'year12-pilot',revision:1,year:12,title:'Year 12 · Applying and explaining',minutes:45,
    description:'Structures, algorithms, objects, relational data and security. Eight short answers and two extended responses; 30 marks.',
    questions:[
      {id:'y12-1',type:'Short answer',title:'Trace a two-dimensional list',topic:'Data structures',chapter:'unit3-structures',
        prompt:'State the final value of grid and the output of print.',
        code:'grid = [[1, 2], [3, 4]]\ngrid[1][0] = grid[0][1] + 5\nprint(grid[1][0])',
        criteria:['Final grid is [[1, 2], [7, 4]].','Printed output is 7.'],
        model:'grid = [[1, 2], [7, 4]]\nOutput: 7\nThe right side reads 2, adds 5, and writes to row 1, column 0 using zero-based indices.',
        mistake:'Row and column indices are zero-based. Only one item changes.'},
      {id:'y12-2',type:'Short answer',title:'Select a dictionary',topic:'Data structures',chapter:'unit3-structures',
        prompt:'A game needs to retrieve item descriptions using unique item IDs. Explain why a dictionary is suitable, and what must be true about its keys.',
        criteria:['Explains mapping an item ID directly to its description/value for retrieval by that ID.','States that keys must be unique; duplicate IDs cannot represent two distinct entries under the same key.'],
        model:'A dictionary maps each item ID to its description, allowing retrieval by that ID rather than finding its position in a list. Each key must be unique; assigning an existing key replaces its associated value in Python.',
        mistake:'A dictionary key is not a numeric position. Do not claim dictionaries automatically reject duplicate assignments.'},
      {id:'y12-3',type:'Short answer',title:'Prepare for binary search',topic:'Algorithms',chapter:'unit3-search',
        prompt:'A list of unique scores will be searched with binary search. State its required ordering condition and explain why that condition matters.',
        criteria:['States that the list must be sorted according to the comparison order used by the algorithm.','Explains that comparing with the middle item then permits eliminating the half that cannot contain the target.'],
        model:'The scores must be sorted in the order assumed by the search, such as ascending order. A comparison with the middle score then identifies which half can contain the target, allowing the other half to be discarded.',
        mistake:'A list being indexed is insufficient. Without ordering, discarding half can discard the target.'},
      {id:'y12-4',type:'Short answer',title:'Trace a bubble-sort pass',topic:'Algorithms',chapter:'unit3-sort',
        prompt:'Starting with [5, 2, 4, 1], perform one left-to-right bubble-sort pass for ascending order. Compare adjacent pairs at indices (0,1), (1,2), then (2,3), swapping each out-of-order pair. State the resulting list and the value now at the final position.',
        criteria:['Resulting list is [2, 4, 1, 5].','Identifies 5 as the value at the final position.'],
        model:'[5,2,4,1] → [2,5,4,1] → [2,4,5,1] → [2,4,1,5].\nThe largest value, 5, reaches the final position after this pass.',
        mistake:'One pass does not fully sort this list. Follow the specified left-to-right convention.'},
      {id:'y12-5',type:'Short answer',title:'Explain method overriding',topic:'Object-oriented programming',chapter:'unit3-inheritance',
        prompt:'Player and Hazard inherit from Actor. Both subclasses define update(). Explain inheritance and overriding in this example.',
        criteria:['Explains that Player and Hazard inherit shared Actor behaviour/attributes, avoiding repeated common code.','Explains that a subclass supplies its own update implementation to specialise behaviour inherited from Actor.'],
        model:'Actor can define shared position and movement behaviour that Player and Hazard inherit. Each subclass overrides update() to specialise its behaviour, such as player input or a hazard patrol.',
        mistake:'Overriding changes a subclass implementation; it does not mean copying every base-class method.'},
      {id:'y12-6',type:'Short answer',title:'Join related records',topic:'SQL',chapter:'unit4-sql',
        prompt:'Member(MemberID, Name) and Loan(LoanID, MemberID) are related by MemberID. Write SQL to display Name and LoanID for matching members and loans.',
        criteria:['Selects Member.Name and Loan.LoanID from the two tables, allowing suitable aliases.','Correctly joins on Member.MemberID = Loan.MemberID.'],
        model:'SELECT Member.Name, Loan.LoanID\nFROM Member\nINNER JOIN Loan ON Member.MemberID = Loan.MemberID;\nEquivalent correct joins and aliases are acceptable. Keyword case and a missing final semicolon do not affect these marks.',
        mistake:'Joining Name to LoanID or omitting the relationship condition does not match the related records.'},
      {id:'y12-7',type:'Short answer',title:'Referential integrity',topic:'Relational databases',chapter:'unit4-design',
        prompt:'Loan.MemberID is a mandatory foreign key referencing Member.MemberID, and foreign-key enforcement is enabled. Explain what happens when a loan references a MemberID that does not exist, and why.',
        criteria:['States that the insert/update is rejected under the stated enforced constraint.','Explains that the constraint prevents an orphan loan and preserves references to existing members.'],
        model:'The operation is rejected because its MemberID does not reference an existing member. This prevents an orphan loan and maintains referential integrity.',
        mistake:'Do not assume a foreign-key label enforces itself in every environment; this question explicitly states enforcement is enabled.'},
      {id:'y12-8',type:'Short answer',title:'Choose a security control',topic:'Security',chapter:'unit4-controls',
        prompt:'A stolen password allows an attacker to attempt a staff account login. Propose one additional login control and explain one limitation of it.',
        criteria:['Proposes an additional authentication factor, preferably phishing-resistant MFA, that is independent of the stolen password.','Explains a relevant limitation such as recovery-channel compromise, stolen sessions, or phishing/push approval attacks for susceptible MFA methods.'],
        model:'Use phishing-resistant multi-factor authentication such as an appropriately configured security key. A stolen password alone would then be insufficient, but account recovery or an already-stolen authenticated session can still be attacked. If proposing one-time codes or push MFA, explain a limitation relevant to that method.',
        mistake:'Changing password length alone does not add a factor. No control removes every attack path.'},
      {id:'y12-9',type:'Extended response',title:'Model an interactive game',topic:'Structures, objects and testing',chapter:'unit3-objects',
        prompt:'A Pygame game uses an 8 × 10 tile map, item descriptions indexed by item ID, a keyboard-controlled player and patrolling hazards. Explain suitable data structures and a class design using Actor, Player and Hazard. Describe how one frame separates state updates from drawing. Propose two tests with expected results. You do not need to implement the complete game.',
        criteria:['Uses a two-dimensional list/array for tile values accessed by row and column.','Uses a dictionary mapping unique item IDs to descriptions or metadata.','Places shared position/movement behaviour in Actor and uses inheritance for Player and Hazard.','Explains overridden update behaviour for input-driven Player and patrol-driven Hazard.','Describes updating state before drawing that state, with drawing not changing gameplay values.','Gives a movement or wall-boundary test with a specific expected outcome.','Gives an item lookup or patrol test with a specific expected outcome.'],
        model:'Store tiles in a 2D list accessed as tiles[row][column], and descriptions in a dictionary such as items["key1"]. Actor holds common position and movement behaviour; Player and Hazard inherit it. Player.update reads input and Hazard.update advances a predictable patrol. Each frame processes events and updates game state before drawing that state. Drawing the HUD must not increment the score. For example, moving right into a wall must leave the player position unchanged; looking up "key1" must return its stated description. Equivalent designs and concrete tests meeting these requirements are acceptable.',
        mistake:'Naming classes is insufficient: explain responsibilities and inherited/overridden behaviour. A test requires an expected outcome.'},
      {id:'y12-10',type:'Extended response',title:'Design a reliable booking change',topic:'Database development and security',chapter:'unit4-sql',
        prompt:'A booking service stores Workshop(WorkshopID, Title, Capacity) and Booking(BookingID, WorkshopID, StudentID). A booking must refer to an existing workshop; a student must not book the same workshop twice. Staff can change capacity. Explain suitable database constraints, how the application should safely use user-supplied values in SQL, one suitable staff access control, and a recovery measure. Include an example check for the duplicate-booking rule.',
        criteria:['Identifies suitable primary keys for Workshop and Booking.','Enforces Booking.WorkshopID as a foreign key to an existing Workshop.','Uses a unique constraint on the pair (WorkshopID, StudentID) to prevent duplicate student bookings.','Uses parameterised SQL to pass user-supplied values separately from the SQL statement, rather than concatenating them.','Tests a second booking for the same StudentID and WorkshopID and expects rejection, with the original booking preserved.','Restricts capacity edits to authorised staff with suitable roles/permissions and explains protecting the data.','Proposes separate regular backups with tested restoration and explains recovery after loss/corruption.'],
        model:'Use WorkshopID and BookingID as primary keys. Enforce the WorkshopID foreign key, and a UNIQUE(WorkshopID, StudentID) constraint. Use parameterised SQL, such as placeholders bound to user-supplied values, so those values are treated as data rather than SQL instructions. Test a second booking of the same workshop for the same student: the duplicate must be rejected and the original retained. Restrict capacity updates to authorised staff roles. Keep separate regular backups and test restoration to support recovery. Equivalent constraints, tests and explained controls are acceptable; exact SQL syntax is not required.',
        mistake:'A foreign key alone does not stop the same student booking twice. Parameterised SQL helps prevent SQL injection; it does not replace access control or validation.'}
    ]}
];
